def count_divisors(n):
    if n <= 0:
        return 0
    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
        i += 1
    return count

results = []
for k in range(1, 16):
    n = 2 * (k**3)
    d_nk3 = count_divisors(n)
    target = 2 * k
    results.append((k, d_nk3, target))

print("k | d(2k^3) | 2k | Match (d=2k)")
for k, d, target in results:
    match = "Yes" if d == target else "No"
    print(f"{k:2} | {d:7} | {target:3} | {match}")

